import { Dispatch, SetStateAction } from 'react';
import { SubmitHandler, UseFormSetError, UseFormSetFocus, UseFormSetValue } from 'react-hook-form';
import { SuperAppEncData } from '~/entities/super-app/model/types';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import {
  selfAuthNum,
  useTestSelfAuthMutation,
  useSelfAuthMutation,
} from '~/entities/mobile-verification/api/use-self-auth-mutation';
import { FormPhase, Inputs, SelfAuthNumParams, SelfAuthParams } from '~/entities/mobile-verification/model/types';
import { setUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { VerificationType } from '~/shared/api/dtos/enums';
import { TEST_INTRO } from '~/shared/config/environment';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { notiBar, snackBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';

type OnSubmitProps = {
  formPhase: FormPhase;
  serverAuthNumber?: string;
  startTimer: () => void;
  setFormPhase: (formPhase: FormPhase) => void;
  setFocus: UseFormSetFocus<Inputs>;
  setValue: UseFormSetValue<Inputs>;
  setServerAuthNumber: Dispatch<SetStateAction<string>>;
  setError: UseFormSetError<Inputs>;
};
export const useOnSubmit = ({
  formPhase,
  serverAuthNumber,
  setFormPhase,
  startTimer,
  setFocus,
  setValue,
  setServerAuthNumber,
  setError,
}: OnSubmitProps) => {
  const { routerState: state } = useGetRouterState<SuperAppEncData>();
  const { navigate } = useNavigate();
  const { mutateAsync: selfAuthApi } = useSelfAuthMutation();
  const { mutateAsync: testSelfAuthApi } = useTestSelfAuthMutation();
  const { openAlertDialog } = useAlertDialog();
  const onSubmit: SubmitHandler<Inputs> = async (data) => {
    const processTestAuthNumberRequest = async () => {
      const param = createSelfAuthParams(data);
      const result = await testSelfAuthApi(param);
      if (
        state?.verificationType === VerificationType.ReSetUser ||
        state?.verificationType === VerificationType.FailSetUser
      ) {
        if (result.cstmrNo !== state.cstmrNo) {
          openAlertDialog({ message: i18n.t('validation:authenticationMismatch') });
          return;
        }
      }

      if (result.authNo) {
        setFormPhase(FormPhase.REQUESTED_AUTH_NUMBER);
        startTimer();
        setServerAuthNumber(result.authNo);
        setValue('authNumber', result.authNo);
        notifyAuthNumberSent();
        notiBar(result.authNo);
      }
    };
    const processTestVerifyAuthNumber = async () => {
      snackBar(i18n.t('validation:authenticationComplete'));
      setUserRes((prev) => ({
        ...prev,
        tbCstmrMastr: {
          ...prev.tbCstmrMastr,
          ...data,
        },
      }));
      if (
        state?.verificationType === VerificationType.ReSetUser ||
        state?.verificationType === VerificationType.FailSetUser
      ) {
        navigate(PATHS.pin.reset, { state: { ...state, ...data } });
        return;
      }
      navigate(PATHS.account.verifyBank, { state: { ...state, ...data } });
      return;
    };
    const processAuthNumberRequest = async () => {
      const param = createSelfAuthParams(data);
      const result = await selfAuthApi(param);

      if (state?.verificationType === VerificationType.ReSetUser) {
        if (result.cstmrNo !== state.cstmrNo) {
          openAlertDialog({ message: i18n.t('validation:authenticationMismatch') });
          return;
        }
      }

      if (result.returnCode === '0000' && result.authSeq) {
        setFormPhase(FormPhase.REQUESTED_AUTH_NUMBER);
        startTimer();
        setServerAuthNumber(result.authSeq);
        notifyAuthNumberSent();
      } else {
        openAlertDialog({ message: result.message });
      }
    };

    const processVerifyAuthNumber = async () => {
      const reqData: SelfAuthNumParams = {
        tbCstmrMastr: {
          authNo: data.authNumber,
          authSeq: serverAuthNumber ?? '',
          ci: state.ci ?? '',
        },
      };
      try {
        const ret = await selfAuthNum(reqData);
        if (!ret) {
          setError('authNumber', {
            type: 'manual',
            message: i18n.t('validation:invalidVerificationCode'),
          });
          snackBar(i18n.t('validation:authenticationFail'));
          setServerAuthNumber('E');
          return;
        }
      } catch (error: any) {
        if (TEST_INTRO === true) {
          if (error?.response?.data?.message) {
            const msg: string = error.response.data.message;
            if (msg.includes('CI가 일치 하지 않습니다.')) {
            } else {
              setError('authNumber', {
                type: 'manual',
                message: i18n.t('validation:invalidVerificationCode'),
              });
              snackBar(i18n.t('validation:authenticationFail'));
              setServerAuthNumber('E');
              return;
            }
          }
        } else {
          setError('authNumber', {
            type: 'manual',
            message: i18n.t('validation:invalidVerificationCode'),
          });
          snackBar(i18n.t('validation:authenticationFail'));
          setServerAuthNumber('E');
          return;
        }
      }

      snackBar(i18n.t('validation:authenticationComplete'));
      if (
        state?.verificationType === VerificationType.ReSetUser ||
        state?.verificationType === VerificationType.FailSetUser
      ) {
        navigate(PATHS.pin.reset, { state: { ...state, ...data } });
        return;
      }

      navigate(PATHS.account.verifyBank, { state: { ...state, ...data } });
      return;
    };

    if (formPhase === FormPhase.HAS_NOT_REQUESTED_AUTH_NUMBER) {
      processTestAuthNumberRequest(); //NICE 목업 API 사용
      //processAuthNumberRequest(); //NICE API 사용
    }

    if (formPhase === FormPhase.REQUESTED_AUTH_NUMBER) {
      processTestVerifyAuthNumber(); //NICE 목업 API 사용
      //processVerifyAuthNumber(); //NICE API 사용
    }
  };

  const notifyAuthNumberSent = () => {
    snackBar(i18n.t('validation:verificationCodeSent'));
    setTimeout(() => {
      setFocus('authNumber');
    }, 150);
  };

  return {
    onSubmit,
  };
};

const createSelfAuthParams = (data: Inputs): SelfAuthParams => {
  return {
    tbCstmrMastr: {
      koreanNm: data.koreanNm,
      rlnmNo: data.rlnmNo,
      telecomTypeCd: data.telecomTypeCd,
      mbtlnum: data.mbtlnum,
      appEsntlNo: '1234567890',
    },
  };
};
