import { useEffect, useRef, useState } from 'react';
import { UseFormClearErrors, UseFormSetError, UseFormSetValue } from 'react-hook-form';
import { DEFAULT_TIME_OUT } from '~/entities/mobile-verification/model/constants';
import { FormPhase, Inputs } from '~/entities/mobile-verification/model/types';
import i18n from '~/shared/i18n/i18n';

type AuthTimerProps = {
  setError: UseFormSetError<Inputs>;
  setFormPhase: (formPhase: FormPhase) => void;
  setValue: UseFormSetValue<Inputs>;
  clearErrors: UseFormClearErrors<Inputs>;
};
export const useAuthTimer = ({ setError, setFormPhase, setValue, clearErrors }: AuthTimerProps) => {
  const [remainingTime, setRemainingTime] = useState(DEFAULT_TIME_OUT);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const minutes = Math.floor(remainingTime / 1000 / 60);
  const seconds = Math.floor((remainingTime / 1000) % 60);
  const remainingTimeText = `${minutes}분${seconds}초`;

  const startTimer = () => {
    timerRef.current = setInterval(() => {
      setRemainingTime((prev) => prev - 1000);
    }, 1000);
  };

  useEffect(() => {
    return () => {
      if (timerRef.current !== null) clearInterval(timerRef.current);
    };
  }, []);

  const handleRetryAuthNumber = async () => {
    clearErrors('authNumber');
    if (timerRef.current !== null) clearInterval(timerRef.current);
    setRemainingTime(DEFAULT_TIME_OUT);
    setFormPhase(FormPhase.HAS_NOT_REQUESTED_AUTH_NUMBER);
    setValue('authNumber', '', { shouldValidate: true });
  };

  useEffect(() => {
    if (remainingTime <= 0) {
      if (timerRef.current !== null) clearInterval(timerRef.current);
      setError('authNumber', {
        type: 'manual',
        message: i18n.t('validation:timeExceeded'),
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [remainingTime]);

  return {
    remainingTime,
    setRemainingTime,
    timerRef,
    startTimer,
    remainingTimeText,
    handleRetryAuthNumber,
  };
};
