import { useMutation, UseMutationOptions } from '@tanstack/react-query';
import axios from 'axios';
import { SelfAuthNumParams, SelfAuthParams, SelfAuthResponse } from '~/entities/mobile-verification/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

export const selfAuth = ({ tbCstmrMastr }: SelfAuthParams) => {
  return resultify(
    axios.post<SelfAuthResponse>(`${API_URLS.realSelfAuth}`, {
      tbCstmrMastr,
    }),
  );
};
export const testSelfAuth = ({ tbCstmrMastr }: SelfAuthParams) => {
  return resultify(
    axios.post<SelfAuthResponse>(`${API_URLS.selfAuth}`, {
      tbCstmrMastr,
    }),
  );
};

export const useSelfAuthMutation = (options?: UseMutationOptions<SelfAuthResponse, CBDCAxiosError, SelfAuthParams>) => {
  const mutation = useMutation<SelfAuthResponse, CBDCAxiosError, SelfAuthParams>({
    ...options,
    mutationFn: ({ tbCstmrMastr }: SelfAuthParams) => selfAuth({ tbCstmrMastr }),
  });

  return {
    ...mutation,
  };
};
export const useTestSelfAuthMutation = (
  options?: UseMutationOptions<SelfAuthResponse, CBDCAxiosError, SelfAuthParams>,
) => {
  const mutation = useMutation<SelfAuthResponse, CBDCAxiosError, SelfAuthParams>({
    ...options,
    mutationFn: ({ tbCstmrMastr }: SelfAuthParams) => testSelfAuth({ tbCstmrMastr }),
  });

  return {
    ...mutation,
  };
};

